-- Shopify full tool surface: customer/orders/fulfillment/discounts/segments/products/returns + AI composites.
-- Idempotent: ON CONFLICT (integration_id, slug) DO NOTHING so re-running is safe.

ON CONFLICT ("integration_id","slug") DO NOTHING;

UPDATE "catalog_tools" SET "hitl_policy" = '{"mode":"always","approverRole":"ADMIN","notifyChannels":["in_app"],"expiresAfterMin":60,"allowModification":true}' WHERE "integration_id"='cat_shopify' AND "slug" IN ('cancel_order','create_one_time_coupon','create_vip_coupon','issue_compensation_coupon');

